package com.petmounts;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small on-screen button to hop on and off. Click it to ride or dismount; hold Alt and drag to move it,
 * like any RuneLite overlay.
 */
class MountButtonOverlay extends Overlay
{
	private static final int SIZE = 34;
	private static final Color BACKGROUND = new Color(30, 30, 30, 190);
	private static final Color RIDING = new Color(110, 225, 110);
	private static final Color IDLE = new Color(120, 120, 120);

	private final BufferedImage icon;
	private final BooleanSupplier visible;
	private final BooleanSupplier riding;
	private final BooleanSupplier canRide;
	private final Runnable onClick;

	final MouseAdapter mouse = new MouseAdapter()
	{
		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			Rectangle b = getBounds();
			if (visible.getAsBoolean() && b != null && b.contains(e.getPoint()) && !e.isAltDown()
				&& e.getButton() == MouseEvent.BUTTON1)
			{
				onClick.run();
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			// Don't let a click on the button also walk your character.
			Rectangle b = getBounds();
			if (visible.getAsBoolean() && b != null && b.contains(e.getPoint()) && !e.isAltDown()
				&& e.getButton() == MouseEvent.BUTTON1)
			{
				e.consume();
			}
			return e;
		}
	};

	MountButtonOverlay(PetMountsPlugin plugin, BufferedImage icon, BooleanSupplier visible, BooleanSupplier riding,
		BooleanSupplier canRide, Runnable onClick)
	{
		super(plugin);
		this.icon = icon;
		this.visible = visible;
		this.riding = riding;
		this.canRide = canRide;
		this.onClick = onClick;
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setResettable(true);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!visible.getAsBoolean())
		{
			return null;
		}
		boolean on = riding.getAsBoolean();
		boolean ready = on || canRide.getAsBoolean();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(BACKGROUND);
		g.fillRoundRect(0, 0, SIZE, SIZE, 8, 8);
		g.setStroke(new BasicStroke(on ? 2f : 1f));
		g.setColor(on ? RIDING : IDLE);
		g.drawRoundRect(0, 0, SIZE - 1, SIZE - 1, 8, 8);
		if (icon != null)
		{
			java.awt.Composite old = g.getComposite();
			if (!ready)
			{
				g.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.4f));
			}
			int h = SIZE - 8;
			int w = Math.round(h * icon.getWidth() / (float) icon.getHeight());
			g.drawImage(icon, (SIZE - w) / 2, 4, w, h, null);
			g.setComposite(old);
		}
		return new Dimension(SIZE, SIZE);
	}
}

package com.petmounts;

import java.awt.Color;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.SpotanimID;

/**
 * The climb-on sparkle and the poofs, built from the game's own graphics and drawn in the world
 * like any spell or teleport effect. Each graphic is recoloured to the pet's colours, keeping the
 * original light and shade so it still looks like the game's own art.
 */
@Slf4j
@Singleton
class MountEffects
{
	/** Sparkles around the player while climbing on. */
	private static final int WINDUP_GRAPHIC = SpotanimID.LEVELUP_ANIM;
	/** Poof when the mount appears or is sent away. */
	private static final int POOF_GRAPHIC = SpotanimID.SMOKEPUFF_LARGE;
	/** Small puff when hopping off for an action and climbing back on. */
	private static final int PUFF_GRAPHIC = SpotanimID.SMALL_SMOKEPUFF;

	/** Cache archive holding graphic (spotanim) definitions. */
	private static final int SPOTANIM_ARCHIVE = 13;

	private static final int AMBIENT = 64;
	private static final int CONTRAST = 850;

	private final Client client;
	private final Map<Integer, Graphic> graphics = new HashMap<>();
	/** Graphics that couldn't be read, so they aren't looked up again every time. */
	private final java.util.Set<Integer> missing = new java.util.HashSet<>();
	/**
	 * Recoloured, lit effect models, reused for every flame or puff that looks the same instead of being rebuilt
	 * each time. Cleared with the effects.
	 */
	private final Map<String, Model> models = new HashMap<>();
	private static final int MAX_MODELS = 32;
	private final List<RuneLiteObject> active = new ArrayList<>();
	private RuneLiteObject windup;

	@Inject
	MountEffects(Client client)
	{
		this.client = client;
	}

	void windup(Color color)
	{
		endWindup();
		windup = spawn(WINDUP_GRAPHIC, color, 0, true);
	}

	void endWindup()
	{
		if (windup != null)
		{
			windup.setActive(false);
			active.remove(windup);
			windup = null;
		}
	}

	void poof(Color color, int height)
	{
		endWindup();
		spawn(POOF_GRAPHIC, color, height, false);
	}

	void puff(Color color, int height)
	{
		spawn(PUFF_GRAPHIC, color, height, false);
	}

	/** Keeps the climb-on sparkle on the player and forgets finished effects. Call every client tick. */
	void tick()
	{
		for (Iterator<RuneLiteObject> it = active.iterator(); it.hasNext(); )
		{
			if (!it.next().isActive())
			{
				it.remove();
			}
		}

		Player me = client.getLocalPlayer();
		if (windup != null && me != null)
		{
			place(windup, me, 0);
		}
	}

	void clear()
	{
		for (RuneLiteObject o : active)
		{
			o.setActive(false);
		}
		active.clear();
		windup = null;
		models.clear();
	}

	// ------------------------------------------------------------------

	private RuneLiteObject spawn(int graphicId, Color color, int height, boolean loop)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		RuneLiteObject obj = create(graphicId, color, (short) 0, 128, loop);
		if (obj == null)
		{
			return null;
		}
		place(obj, me, height);
		obj.setActive(true);
		active.add(obj);
		return obj;
	}

	/**
	 * Plays a graphic once at a spot in the world, e.g. a flame under a fiery mount.
	 *
	 * @param recolorTo if not 0, every face is recoloured to this colour (keeping its lightness)
	 * @param scale size, 128 = as the game draws it
	 */
	RuneLiteObject spawnAt(int graphicId, short recolorTo, LocalPoint lp, int plane, int height, int orientation,
		int scale)
	{
		if (lp == null || active.size() >= MAX_ACTIVE)
		{
			return null;
		}
		RuneLiteObject obj = create(graphicId, null, recolorTo, scale, false);
		if (obj == null)
		{
			return null;
		}
		obj.setLocation(lp, plane);
		obj.setZ(Perspective.getTileHeight(client, lp, plane) - height);
		obj.setOrientation(orientation);
		obj.setActive(true);
		active.add(obj);
		return obj;
	}

	/** Effects on screen at once, at most: plenty for trails, and keeps a crowd of fiery mounts cheap. */
	private static final int MAX_ACTIVE = 40;

	private RuneLiteObject create(int graphicId, Color color, short recolorTo, int scale, boolean loop)
	{
		Graphic g = graphic(graphicId);
		if (g == null)
		{
			return null;
		}
		Animation anim = g.animation >= 0 ? client.loadAnimation(g.animation) : null;
		if (anim == null && !loop)
		{
			return null; // a one-shot needs its animation to know when to end
		}

		String key = graphicId + ":" + (color == null ? "-" : color.getRGB()) + ":" + recolorTo + ":" + scale;
		Model model = models.get(key);
		if (model == null)
		{
			model = buildModel(g, color, recolorTo, scale);
			if (model == null)
			{
				return null;
			}
			if (models.size() >= MAX_MODELS)
			{
				models.clear();
			}
			models.put(key, model);
		}

		RuneLiteObject obj = client.createRuneLiteObject();
		obj.setModel(model);
		// Looping effects stay until removed; one-shots switch themselves off when their animation ends.
		obj.setShouldLoop(loop);
		obj.setAnimation(anim);
		return obj;
	}

	/** The graphic's model, resized, recoloured and lit. Null if it isn't loaded. */
	private Model buildModel(Graphic g, Color color, short recolorTo, int scale)
	{
		ModelData md = client.loadModelData(g.model);
		if (md == null)
		{
			return null;
		}
		md = md.shallowCopy().cloneColors();
		if (g.recolorFind != null)
		{
			for (int i = 0; i < Math.min(g.recolorFind.length, g.recolorReplace.length); i++)
			{
				md.recolor(g.recolorFind[i], g.recolorReplace[i]);
			}
		}
		if (g.retextureFind != null)
		{
			md = md.cloneTextures();
			for (int i = 0; i < Math.min(g.retextureFind.length, g.retextureReplace.length); i++)
			{
				md.retexture(g.retextureFind[i], g.retextureReplace[i]);
			}
		}
		for (int i = 0; i < Math.floorMod(g.rotation, 360) / 90; i++)
		{
			md = md.cloneVertices().rotateY90Ccw();
		}
		int sx = g.resizeX * scale / 128, sy = g.resizeY * scale / 128;
		if (sx != 128 || sy != 128)
		{
			md = md.cloneVertices().scale(Math.max(1, sx), Math.max(1, sy), Math.max(1, sx));
		}
		tint(md, color);
		if (recolorTo != 0)
		{
			recolor(md, recolorTo);
		}

		return md.light(AMBIENT + g.ambient, CONTRAST + g.contrast, -30, -50, -30);
	}

	/** Recolours every face to this colour's hue and saturation, keeping each face's own lightness. */
	private static void recolor(ModelData md, short target)
	{
		short[] colors = md.getFaceColors();
		if (colors == null)
		{
			return;
		}
		int hue = JagexColor.unpackHue(target), sat = JagexColor.unpackSaturation(target);
		int lum = JagexColor.unpackLuminance(target);
		for (int i = 0; i < colors.length; i++)
		{
			int own = JagexColor.unpackLuminance(colors[i]);
			colors[i] = JagexColor.packHSL(hue, sat, Math.min(127, (own + lum) / 2));
		}
	}

	private void place(RuneLiteObject obj, Player me, int height)
	{
		LocalPoint lp = me.getLocalLocation();
		if (lp == null || me.getWorldView() == null)
		{
			return;
		}
		int plane = me.getWorldView().getPlane();
		obj.setLocation(lp, plane);
		obj.setZ(Perspective.getTileHeight(client, lp, plane) - height);
		obj.setOrientation(me.getCurrentOrientation());
	}

	/**
	 * Recolours every face to the given colour's hue and saturation while keeping each face's
	 * own lightness, so the graphic keeps its shading and just changes colour.
	 */
	static void tint(ModelData md, Color color)
	{
		if (color == null)
		{
			return;
		}
		short target = JagexColor.rgbToHSL(color.getRGB(), 1.0);
		int hue = JagexColor.unpackHue(target);
		int sat = JagexColor.unpackSaturation(target); // grey pets give grey smoke
		short[] colors = md.getFaceColors();
		if (colors == null)
		{
			return;
		}
		for (int i = 0; i < colors.length; i++)
		{
			int lum = JagexColor.unpackLuminance(colors[i]);
			colors[i] = JagexColor.packHSL(hue, sat, lum);
		}
	}

	// ------------------------------------------------------------------
	// Reading graphic definitions from the game cache
	// ------------------------------------------------------------------

	private Graphic graphic(int id)
	{
		Graphic cached = graphics.get(id);
		if (cached != null || missing.contains(id))
		{
			return cached;
		}
		IndexDataBase configs = client.getIndexConfig();
		byte[] data = configs == null ? null : configs.loadData(SPOTANIM_ARCHIVE, id);
		if (data == null)
		{
			return null; // the cache may not be ready yet: try again later
		}
		try
		{
			Graphic g = Graphic.decode(data);
			if (g != null)
			{
				graphics.put(id, g);
			}
			else
			{
				missing.add(id);
			}
			return g;
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read graphic {}", id, e);
			missing.add(id);
			return null;
		}
	}

	/**
	 * A graphic (spotanim) definition. The opcode layout follows the game's cache format; the
	 * handling of opcode 10 (a flag with no data) is from Rapid Mounts by RapidUrsa (BSD 2-Clause).
	 */
	static final class Graphic
	{
		int model;
		int animation = -1;
		int resizeX = 128;
		int resizeY = 128;
		int rotation;
		int ambient;
		int contrast;
		short[] recolorFind;
		short[] recolorReplace;
		short[] retextureFind;
		short[] retextureReplace;

		static Graphic decode(byte[] data)
		{
			Reader in = new Reader(data);
			Graphic g = new Graphic();
			for (int op = in.u8(); op != 0; op = in.u8())
			{
				switch (op)
				{
					case 1:
						g.model = in.u16();
						break;
					case 2:
						g.animation = in.u16();
						break;
					case 3:
						g.model = in.i32();
						break;
					case 4:
						g.resizeX = in.u16();
						break;
					case 5:
						g.resizeY = in.u16();
						break;
					case 6:
						g.rotation = in.u16();
						break;
					case 7:
						g.ambient = in.u8();
						break;
					case 8:
						g.contrast = in.u8();
						break;
					case 9:
						in.skipString();
						break;
					case 10:
						break;
					case 40:
					{
						int n = in.u8();
						g.recolorFind = new short[n];
						g.recolorReplace = new short[n];
						for (int i = 0; i < n; i++)
						{
							g.recolorFind[i] = (short) in.u16();
							g.recolorReplace[i] = (short) in.u16();
						}
						break;
					}
					case 41:
					{
						int n = in.u8();
						g.retextureFind = new short[n];
						g.retextureReplace = new short[n];
						for (int i = 0; i < n; i++)
						{
							g.retextureFind[i] = (short) in.u16();
							g.retextureReplace[i] = (short) in.u16();
						}
						break;
					}
					default:
						throw new IllegalStateException("unknown graphic opcode " + op);
				}
			}
			return g.model > 0 ? g : null;
		}
	}

	private static final class Reader
	{
		private final byte[] data;
		private int pos;

		Reader(byte[] data)
		{
			this.data = data;
		}

		int u8()
		{
			return data[pos++] & 0xFF;
		}

		int u16()
		{
			return (u8() << 8) | u8();
		}

		int i32()
		{
			return (u16() << 16) | u16();
		}

		void skipString()
		{
			while (data[pos++] != 0)
			{
				// skip to the terminating zero
			}
		}
	}
}

package com.petmounts;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * The little things each mount does on its own: idle tricks played now and then while standing still, a sound now
 * and then, and a trail for the showpiece mounts.
 *
 * Every trick is one of the game's own animations made for the same skeleton as the mount (checked against the
 * cache), so it plays on the mount exactly as it does on the creature in the game. Sounds are the creature's own
 * sound effects, taken from its animations.
 */
final class MountExtras
{
	/** Dog dig animations: every dog, wolf and hound shares one skeleton, so they can all dig. */
	static final int DIG = 14498, DIG_SMALL = 14499;

	enum Trail
	{
		/** Little flames at its feet. */
		FIRE,
		/** Flames, and glowing lava footprints. */
		LAVA,
		/** Icy mist. */
		FROST,
		/** Ghostly mist. */
		GHOST
	}

	private static final Map<Integer, int[]> TRICKS = buildTricks();
	private static final Map<Integer, Integer> SOUNDS = buildSounds();
	private static final Map<String, Trail> TRAILS = buildTrails();

	private MountExtras()
	{
	}

	/** Animations this mount plays now and then while standing still, or null if it has none. */
	static int[] tricks(int npcId)
	{
		return TRICKS.get(npcId);
	}

	/** A sound this mount makes now and then, or -1. */
	static int sound(int npcId)
	{
		return SOUNDS.getOrDefault(npcId, -1);
	}

	/** The trail this mount leaves, by name, or null. */
	static Trail trail(String name)
	{
		return name == null ? null : TRAILS.get(name.toLowerCase(Locale.ROOT));
	}

	private static void put(Map<Integer, int[]> m, int[] tricks, int... ids)
	{
		for (int id : ids)
		{
			m.put(id, tricks);
		}
	}

	private static void put(Map<Integer, Integer> m, int sound, int... ids)
	{
		for (int id : ids)
		{
			m.put(id, sound);
		}
	}

	private static Map<Integer, int[]> buildTricks()
	{
		Map<Integer, int[]> m = new HashMap<>();
		// cats arch their backs and paw at things
		put(m, new int[]{1823, 2663},
			395, 540, 541, 1619, 1620, 1621, 1622, 1623, 1624, 1625, 1626, 1627, 1628, 1629, 1630, 1631, 1632, 2782,
			3498, 5584, 5585, 5586, 5587, 5588, 5589, 5590, 5591, 5592, 5593, 5594, 5595, 5596, 5597, 5598, 5599, 5600,
			5601, 5602, 5603, 5604, 6661, 6662, 6663, 6664, 6665, 6666, 6667, 6668, 6683, 6684, 6685, 6686, 6687, 6688,
			6689, 6690, 6691, 6692, 6693, 6694, 6695, 6696);
		// puppies and small dogs dig
		put(m, new int[]{14499},
			964, 3099, 16364, 16365, 16366, 16379, 16380, 16381, 16394, 16395, 16396, 16433, 16434, 16435, 16436, 16437,
			16438, 16439, 16440, 16441, 16442, 16443, 16444, 16445, 16446, 16447, 16448, 16449, 16450, 16451, 16452,
			16453, 16454, 16455, 16456, 16457, 16458, 16459, 16460, 16461, 16462, 16463, 16464, 16465, 16466, 16467,
			16468, 16543, 16544, 16545, 16558, 16559, 16560, 16573, 16574, 16575);
		// dragons rear up and breathe fire
		put(m, new int[]{81},
			239, 243, 245, 248, 252, 260, 268, 270, 272, 274, 817, 1871, 2918, 2919, 5873, 6593, 6636, 6652, 7039, 7273,
			7274, 7275, 7940, 8030, 8031, 9033, 9047, 14922);
		// dogs, wolves and hounds dig
		put(m, new int[]{14498},
			104, 106, 107, 109, 114, 3426, 4185, 6296, 7232, 12548, 12550, 14237, 16361, 16362, 16363, 16367, 16368,
			16369, 16370, 16371, 16372, 16373, 16374, 16375, 16376, 16377, 16378, 16382, 16383, 16384, 16385, 16386,
			16387, 16388, 16389, 16390, 16391, 16392, 16393, 16404, 16540, 16541, 16542, 16546, 16547, 16548, 16549,
			16550, 16551, 16552, 16553, 16554, 16555, 16556, 16557, 16561, 16562, 16563, 16564, 16565, 16566, 16567,
			16568, 16569, 16570, 16571, 16572);
		// bears rear up and stomp
		put(m, new int[]{8835},
			2838, 2839, 6503, 11986);
		// cattle graze
		put(m, new int[]{1735},
			2790, 15625, 15631, 15633);
		// demons raise their arms
		put(m, new int[]{69},
			425, 6634, 6647, 7671);
		// frogs hop
		put(m, new int[]{10957},
			477, 478);
		// unicorns and stags rear and kick
		put(m, new int[]{6376},
			1845, 2837, 2849);
		// camels eat
		put(m, new int[]{1896},
			2835, 4652);
		// Cerberus howls
		put(m, new int[]{4494},
			5862);
		// chickens flutter
		put(m, new int[]{5380},
			1173, 1175);
		// goats graze
		put(m, new int[]{1736},
			1792);
		// penguins flap, preen and wave
		put(m, new int[]{5699, 5700, 5695},
			830);
		// skeletal wyverns breathe ice
		put(m, new int[]{2988},
			466);
		// terror dogs look around
		put(m, new int[]{5623},
			6473);
		return m;
	}

	private static Map<Integer, Integer> buildSounds()
	{
		Map<Integer, Integer> m = new HashMap<>();
		// cats purr
		put(m, 340,
			395, 540, 541, 1619, 1620, 1621, 1622, 1623, 1624, 1625, 1626, 1627, 1628, 1629, 1630, 1631, 1632, 2782,
			3498, 5584, 5585, 5586, 5587, 5588, 5589, 5590, 5591, 5592, 5593, 5594, 5595, 5596, 5597, 5598, 5599, 5600,
			5601, 5602, 5603, 5604, 6661, 6662, 6663, 6664, 6665, 6666, 6667, 6668, 6683, 6684, 6685, 6686, 6687, 6688,
			6689, 6690, 6691, 6692, 6693, 6694, 6695, 6696);
		// spiders skitter
		put(m, 6963,
