	/** Shows the latest state. Call on the Swing thread. */
	void show(State s)
	{
		if (s.sameAs(shown))
		{
			return;
		}
		shown = s;
		updating = true;
		petLabel.setText(s.petName == null ? "No pet following you" : s.petName);
		statusLabel.setText(s.status);
		statusLabel.setForeground(s.riding || s.canRide ? READY : ColorScheme.LIGHT_GRAY_COLOR);
		rideButton.setText(s.riding ? "Dismount" : "Ride");
		rideButton.setEnabled(s.riding || s.canRide);
		if (!s.favourites.equals(listedFavourites))
		{
			fillMountList(s.favourites);
		}
		mountBox.setSelectedItem(nameOfChoice(s.chosen));
		favouriteButton.setText(s.favourites.contains(s.chosen) ? "Unfavourite" : "Favourite");
		favouriteButton.setEnabled(s.chosen > 0);
		saddleStyleBox.setSelectedItem(s.saddleStyle);
		saddleBox.setSelected(s.saddle);
		reinsBox.setSelected(s.reins);
		motionBox.setSelected(s.motion);
		everyoneBox.setSelected(s.everyone);
		heldBox.setSelected(s.hideHeld);
		capeBox.setSelected(s.hideCape);
		tweakTitle.setText(s.petName == null ? "Adjustments for your pet" : "Adjustments for " + s.petName);
		poseBox.setSelectedItem(s.tweaks.pose);
		sizeSlider.setValue(s.tweaks.size);
		heightSlider.setValue(s.tweaks.seatHeight);
		forwardSlider.setValue(s.tweaks.seatForward);
		setEnabledDeep(tweakPanel, s.petName != null && s.canRide);
		updating = false;
	}

	/** Fills the Mount list: your pet, then favourites, then every other mount, each alphabetically. */
	private void fillMountList(java.util.Set<Integer> favourites)
	{
		boolean was = updating;
		updating = true;
		listedFavourites = new java.util.HashSet<>(favourites);
		mountCell.favourites.clear();
		mountBox.removeAllItems();
		mountBox.addItem(YOUR_PET);
		for (java.util.Map.Entry<String, Integer> e : MountFits.choices().entrySet())
		{
			if (favourites.contains(e.getValue()))
			{
				mountBox.addItem(e.getKey());
				mountCell.favourites.add(e.getKey());
			}
		}
		for (java.util.Map.Entry<String, Integer> e : MountFits.choices().entrySet())
		{
			if (!favourites.contains(e.getValue()))
			{
				mountBox.addItem(e.getKey());
			}
		}
		updating = was;
	}

	/** One row of the Mount list: the mount's picture and its name, like a card. */
	private static final class MountCell extends JPanel implements ListCellRenderer<String>
	{
		private static final Color GOLD = new Color(255, 200, 40);
		private final MountIcons icons;
		private final JLabel picture = new JLabel();
		private final JLabel name = new JLabel();
		/** Names of starred mounts, shown in gold. */
		final java.util.Set<String> favourites = new java.util.HashSet<>();

		MountCell(MountIcons icons)
		{
			this.icons = icons;
			setLayout(new BorderLayout(8, 0));
			picture.setPreferredSize(new Dimension(MountIcons.WIDTH, MountIcons.HEIGHT));
			picture.setHorizontalAlignment(JLabel.CENTER);
			name.setFont(FontManager.getRunescapeBoldFont());
			name.setForeground(Color.WHITE);
			add(picture, BorderLayout.WEST);
			add(name, BorderLayout.CENTER);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends String> list, String value, int index,
			boolean selected, boolean focused)
		{
			ImageIcon icon = icons.get(value);
			picture.setIcon(icon);
			picture.setVisible(icon != null);
			name.setText(value);
			name.setForeground(favourites.contains(value) ? GOLD : Color.WHITE);
			setToolTipText(favourites.contains(value) ? value + " (favourite)" : value);
			boolean inList = index >= 0;
			setBackground(inList && selected ? ColorScheme.DARK_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createCompoundBorder(
				inList ? BorderFactory.createCompoundBorder(
					new EmptyBorder(2, 2, 2, 2),
					BorderFactory.createLineBorder(selected ? GOLD : ColorScheme.MEDIUM_GRAY_COLOR, selected ? 2 : 1))
					: new EmptyBorder(0, 0, 0, 0),
				new EmptyBorder(icon != null ? 2 : 8, 4, icon != null ? 2 : 8, 4)));
			return this;
		}
	}

	private static String nameOfChoice(int npcId)
	{
		if (npcId > 0)
		{
			for (java.util.Map.Entry<String, Integer> e : MountFits.choices().entrySet())
			{
				if (e.getValue() == npcId)
				{
					return e.getKey();
				}
			}
		}
		return YOUR_PET;
	}

	private void tweaksChanged()
	{
		if (updating)
		{
			return;
		}
		RiderPose pose = (RiderPose) poseBox.getSelectedItem();
		actions.saveTweaks(new PetTweaks(sizeSlider.getValue(), heightSlider.getValue(), forwardSlider.getValue(), pose));
	}

	private void checkbox(JCheckBox box, String key)
	{
		box.setFocusPainted(false);
		box.addActionListener(e ->
		{
			if (!updating)
			{
				actions.setOption(key, box.isSelected());
			}
		});
	}

	private JSlider slider(int min, int max, int value)
	{
		JSlider s = new JSlider(min, max, value);
		s.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Save when the player lets go, not on every step of the drag.
		s.addChangeListener(e ->
		{
			if (!s.getValueIsAdjusting())
			{
				tweaksChanged();
			}
		});
		return s;
	}

	private JPanel labelled(String text, JSlider s)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel value = new JLabel(String.valueOf(s.getValue()));
		value.setFont(FontManager.getRunescapeSmallFont());
		s.addChangeListener(e -> value.setText(String.valueOf(s.getValue())));
		JPanel head = new JPanel(new BorderLayout());
		head.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		head.add(small(text), BorderLayout.WEST);
		head.add(value, BorderLayout.EAST);
		p.add(head, BorderLayout.NORTH);
		p.add(s, BorderLayout.CENTER);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));
		return p;
	}

	private static JLabel small(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		return l;
	}

	private static <T extends Component> T left(T c)
	{
		if (c instanceof javax.swing.JComponent)
		{
			((javax.swing.JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		return c;
	}

	private static void setEnabledDeep(Component c, boolean enabled)
	{
		c.setEnabled(enabled);
		if (c instanceof java.awt.Container)
		{
			for (Component child : ((java.awt.Container) c).getComponents())
			{
				setEnabledDeep(child, enabled);
			}
		}
	}

	/** Convenience for the plugin: run an action with the panel's state. */
	static Consumer<State> onSwing(MountStablePanel panel)
	{
		return s -> javax.swing.SwingUtilities.invokeLater(() -> panel.show(s));
	}
}

package com.petmounts;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Predicate;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.WorldType;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.VarbitID;

/**
 * "Everyone rides": shows other players riding the pets following them, on your screen only.
 *
 * Every nearby player with a rideable pet following them is drawn sitting on it, using the same mounts, saddles,
 * reins and motion as your own. It's purely what your client draws; other players see nothing different.
 *
 * Players shown riding can't be clicked (their real model is hidden), so it switches off in the Wilderness and
 * on PvP worlds, and holding Shift shows everyone normally for trading or following.
 */
final class OtherRiders
{
	/** Game ticks a rider stays off their mount after an action animation (skilling, fighting). */
	private static final int ACTION_GRACE_TICKS = 3;
	/** Game ticks to keep trying to build a pet's mount (while its models load) before giving up on it. */
	private static final int MAX_BUILD_TRIES = 5;
	/** How close a player must be to a pet to be taken as its owner when the pet isn't facing anyone. */
	private static final int OWNER_RANGE = 2 * 128;
	/** How much nearer (in local units, 3 tiles) a rider already shown counts as, when picking who to show. */
	private static final int KEEP_SHOWN_BONUS = 3 * 128;

	private final Client client;
	private final PetModels models;
	/** Whether a pet may be ridden (the same rules as your own pets). */
	private final Predicate<NPCComposition> rideable;
	/** Size for a pet's mount (settings and the pet's saved adjustment), so it looks the same whoever rides it. */
	private final Function<NPCComposition, Float> sizeFor;
	/** How a rider on this pet looks (settings and the pet's saved adjustments). */
	private final Function<NPCComposition, MountRig.Style> styleFor;

	private final Map<Player, MountRig> rigs = new HashMap<>();
	private final Map<Player, SpeedTracker> speeds = new HashMap<>();
	private final Map<Player, Integer> busyUntil = new HashMap<>();
	/** Built mounts by pet NPC id, shared by every rider on that pet. */
	private final Map<Integer, PetModels.Built> built = new HashMap<>();
	/** Failed attempts to build a mount per pet NPC id (one per game tick); pets that keep failing are left alone. */
	private final Map<Integer, Integer> failures = new HashMap<>();
	/** The game tick each pet's mount was last tried. */
	private final Map<Integer, Integer> lastTry = new HashMap<>();
	/** The real players and pets hidden this frame (their riders are drawn instead). */
	private final Set<Renderable> hidden = new HashSet<>();

	OtherRiders(Client client, PetModels models, Predicate<NPCComposition> rideable,
		Function<NPCComposition, Float> sizeFor, Function<NPCComposition, MountRig.Style> styleFor)
	{
		this.client = client;
		this.models = models;
		this.rideable = rideable;
		this.sizeFor = sizeFor;
		this.styleFor = styleFor;
	}

	/** Whether this player or pet is drawn as a rider right now. */
	boolean hides(Renderable renderable)
	{
		return hidden.contains(renderable);
	}

	/** Mounts of other players being shown right now. */
	java.util.List<MountRig> visibleRigs()
	{
		java.util.List<MountRig> out = new ArrayList<>();
		for (MountRig rig : rigs.values())
		{
			if (rig.isVisible())
			{
				out.add(rig);
			}
		}
		return out;
	}

	/** The players shown riding under this point on screen, nearest last (as the game lists them). */
	List<Player> ridersAt(java.awt.Point mouse)
	{
		List<Player> found = new ArrayList<>();
		for (MountRig rig : rigs.values())
		{
			java.awt.Shape area = rig.isVisible() ? rig.screenArea() : null;
			if (area != null && area.contains(mouse))
			{
				found.add(rig.player());
			}
		}
		return found;
	}

	/** Whether showing others riding makes sense here: never where players need to be clicked to fight. */
	boolean allowedHere()
	{
		return !WorldType.isPvpWorld(client.getWorldType())
			&& !client.getWorldType().contains(WorldType.PVP_ARENA)
			&& client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 0;
	}

	/** Called every game tick to note who is busy (skilling, fighting) and should step off. */
	void gameTick(int tick)
	{
		for (Player p : rigs.keySet())
		{
			if (p.getAnimation() != -1 || isFighting(p))
			{
				busyUntil.put(p, tick + ACTION_GRACE_TICKS);
			}
		}
	}

	/** Takes everyone off their mounts for now, keeping the mounts ready (Shift held, loading, Wilderness). */
	void hideAll()
	{
		hidden.clear();
		for (Map.Entry<Player, MountRig> e : rigs.entrySet())
		{
			SpeedTracker speed = speeds.get(e.getKey());
			e.getValue().hide(speed != null && speed.isMoving());
		}
	}

	/**
	 * Draws everyone riding for this client tick.
	 *
	 * @param max the most riders to show, nearest first
	 */
	void update(int tick, int max)
	{
		Player me = client.getLocalPlayer();
		if (me == null || me.getLocalLocation() == null)
		{
			clear();
			return;
		}

		// Everyone else's pets, with the player each one follows.
		List<NPC> pets = new ArrayList<>();
		Map<NPC, Player> owners = new HashMap<>();
		List<Player> players = new ArrayList<>();
		for (Player p : client.getTopLevelWorldView().players())
		{
			players.add(p);
		}
		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			if (npc == client.getFollower())
			{
				continue;
			}
			NPCComposition comp = PetModels.compositionOf(npc);
			if (!PetModels.isOwnablePet(comp) || failures.getOrDefault(comp.getId(), 0) >= MAX_BUILD_TRIES
				|| !rideable.test(comp))
			{
				continue;
			}
			Player owner = ownerOf(npc, comp, me, players);
			if (owner != null)
			{
				pets.add(npc);
				owners.put(npc, owner);
			}
		}
		// Nearest first. Riders already shown keep their place a little longer, so riders at the edge of the
		// limit don't flicker on and off as people move around.
		LocalPoint here = me.getLocalLocation();
		pets.sort((a, b) -> Integer.compare(rank(here, a, owners), rank(here, b, owners)));

		Set<Player> shown = new HashSet<>();
		hidden.clear();
		for (NPC pet : pets)
		{
			if (shown.size() >= max)
			{
				break;
			}
			Player owner = owners.get(pet);
			if (shown.contains(owner) || owner.getLocalLocation() == null)
			{
				continue;
			}
			NPCComposition comp = PetModels.compositionOf(pet);
			MountRig rig = rigs.get(owner);
			if (rig == null || rig.npcId() != comp.getId())
			{
				PetModels.Built b = built(comp, tick);
				if (b == null)
				{
					continue; // not loaded yet
				}
				if (rig != null)
				{
					rig.hide(false);
				}
				rig = new MountRig(client, owner, b);
				rigs.put(owner, rig);
			}
			SpeedTracker speed = speeds.computeIfAbsent(owner, p -> new SpeedTracker());
			speed.track(owner);

			if (busyUntil.getOrDefault(owner, -1) > tick)
			{
				rig.hide(speed.isMoving());
				shown.add(owner); // keep their mount ready for when they're done
				continue;
			}

			rig.update(pet, speed.gait(), styleFor.apply(comp), false);
			shown.add(owner);
			hidden.add(owner);
			hidden.add(pet);
		}

		// Riders who left, dismissed their pet, or are now too far away.
		rigs.entrySet().removeIf(e ->
		{
			if (shown.contains(e.getKey()))
			{
				return false;
			}
			e.getValue().hide(false);
			return true;
		});
		speeds.keySet().retainAll(rigs.keySet());
		busyUntil.keySet().retainAll(rigs.keySet());
	}

	/** The mount for this pet, built once and shared by everyone riding one. Null while it can't be built. */
	private PetModels.Built built(NPCComposition comp, int tick)
	{
		PetModels.Built b = built.get(comp.getId());
		if (b != null || lastTry.getOrDefault(comp.getId(), -1) == tick)
		{
			return b; // at most one try per game tick
		}
		lastTry.put(comp.getId(), tick);
		b = models.build(comp, sizeFor.apply(comp));
		if (b == null)
		{
			failures.merge(comp.getId(), 1, Integer::sum); // not loaded yet, or no seat on it
			return null;
		}
		built.put(comp.getId(), b);
		return b;
	}

	/** Sits every shown rider on their mount for the frame about to be drawn. */
	void place()
	{
		for (MountRig rig : rigs.values())
		{
			if (rig.isVisible())
			{
				rig.place();
			}
		}
	}

	/** Shows everyone normally again and lets go of their mounts. */
	void clear()
	{
		for (MountRig rig : rigs.values())
		{
			rig.hide(false);
		}
		rigs.clear();
		speeds.clear();
		busyUntil.clear();
		hidden.clear();
	}

	/** Forgets everyone without touching them (after logout or a world hop, when they're gone anyway). */
	void forget()
	{
		for (MountRig rig : rigs.values())
		{
			rig.forget();
			rig.hide(false);
		}
		rigs.clear();
		speeds.clear();
		busyUntil.clear();
		hidden.clear();
	}

	/** Settings changed: rebuild every mount with them. */
	void rebuild()
	{
		clear();
		built.clear();
		failures.clear();
		lastTry.clear();
	}

	/**
	 * The player a pet belongs to: the one it's following (pets face their owner), or failing that, for a
	 * follower, the only other player right next to it. Null if it's yours or it can't be told.
	 */
	private static Player ownerOf(NPC pet, NPCComposition comp, Player me, List<Player> players)
	{
		Actor facing = pet.getInteracting();
		if (facing instanceof Player)
		{
			return facing == me ? null : (Player) facing;
		}
		LocalPoint lp = pet.getLocalLocation();
		if (lp == null || !comp.isFollower())
		{
			return null;
		}
		Player only = null;
		for (Player p : players)
		{
			LocalPoint pp = p.getLocalLocation();
			if (pp == null || pp.distanceTo(lp) > OWNER_RANGE)
			{
				continue;
			}
			if (p == me || only != null)
			{
				return null; // yours, or too crowded to tell
			}
			only = p;
		}
		return only;
	}

	private int rank(LocalPoint here, NPC pet, Map<NPC, Player> owners)
	{
		int d = distance(here, pet);
		MountRig rig = rigs.get(owners.get(pet));
		return rig != null && rig.isVisible() && d != Integer.MAX_VALUE ? d - KEEP_SHOWN_BONUS : d;
	}

	private static int distance(LocalPoint here, NPC npc)
	{
		LocalPoint lp = npc.getLocalLocation();
		return lp == null ? Integer.MAX_VALUE : here.distanceTo(lp);
	}

	/** Fighting a monster. (Facing another player is usually following or trading, so it doesn't count.) */
	private static boolean isFighting(Player p)
	{
		Actor target = p.getInteracting();
		return target instanceof NPC && ((NPC) target).getCombatLevel() > 0;
	}
}

package com.petmounts;

import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;

/**
 * Plays an animation faster or slower. Used when running on a pet that has no run animation: its walk plays
 * at running pace, so its legs keep up with the ground instead of sliding.
 */
final class PacedAnimationController extends AnimationController
{
	private float pace = 1f;
	private float carry;
	/** Client ticks played so far, for {@link #cycle()}. */
	private float played;
	private final int length;

	PacedAnimationController(Client client, Animation animation)
	{
		super(client, animation);
		this.length = lengthOf(animation);
	}

	private static int lengthOf(Animation animation)
	{
		if (animation == null)
		{
			return 0;
		}
		if (animation.isMayaAnim())
		{
			return animation.getDuration();
		}
		int total = 0;
		int[] lengths = animation.getFrameLengths();
		if (lengths != null)
		{
			for (int l : lengths)
			{
				total += Math.max(0, l);
			}
		}
		return total;
	}

	/** How far through one loop of the animation it is, 0 to 1. Smooth, for timing the rider's sway. */
	float cycle()
	{
		return length <= 0 ? 0 : (played % length) / length;
	}

	/** Whether the animation has played all the way through at least once. */
	boolean playedOnce()
	{
		return length <= 0 || played >= length;
	}

	void setPace(float pace)
	{
		this.pace = Math.max(0.25f, Math.min(3f, pace));
	}

	@Override
	public void tick(int ticks)
	{
		played += ticks * pace;
		if (length > 0 && played > length * 1000f)
		{
			played %= length;
		}
		carry += ticks * pace;
		int whole = (int) carry;
		carry -= whole;
		if (whole > 0)
		{
			super.tick(whole);
		}
	}
}

package com.petmounts;

import java.awt.Color;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.client.util.Text;

/**
 * Loads pets from the game's cache and turns them into mounts: enlarged, lowered if they float, lit the way the
 * game lights them, with the seat worked out. Shared by your own mount and other players' mounts.
 */
@Slf4j
final class PetModels
{
	static final int SCALE_BASE = 128;
	/** Floating pets are lowered so their underside hovers no more than this above the ground. */
	static final int MAX_HOVER = 12;
	/** Pets grow until the seat is about this high: pony height, so legs hang down naturally. */
	static final int TARGET_SEAT_HEIGHT = 90;
	/** Seat height for pets you ride on the shoulders of. */
	static final int SHOULDER_SEAT_HEIGHT = 200;
	/**
	 * The biggest a mount may be (before the player's size settings): about 2.5 tiles long, 3 tiles wide and
	 * 2 tiles tall. Long, wide and tall pets (wings, tails, legs, necks) are kept to this even if their back
	 * ends up lower, so no mount towers over everything around it.
	 */
	static final int MAX_LENGTH = 320;
	static final int MAX_WIDTH = 384;
	static final int MAX_HEIGHT = 250;
	/** The lowest seat each pose works on: below this the legs would go through the ground. */
	private static final int MIN_WIDE_SEAT = 85;
	private static final int MIN_EXTRA_WIDE_SEAT = 42;
	static final float MAX_GROWTH = 4.5f;
	/** Untuned pets at least this wide at the seat (half-width, after enlarging) get the Extra wide pose. */
	static final int EXTRA_WIDE_HALF_WIDTH = 40;
	/** The game's base lighting for NPC models; each NPC adds its own ambient and contrast on top. */
	private static final int NPC_AMBIENT = 64;
	private static final int NPC_CONTRAST = 850;

	/** A pet made into a mount. */
	static final class Built
	{
		final int npcId;
		final String petName;
		final Model model;
		final int a, b, c;
		final float wa, wb, wc;
		final int mountHeight;
		final RiderPose autoPose;
		final Color[] palette;
		/** Gold or silver saddle fittings, whichever suits the pet's colours. */
		final short trim;
		/**
		 * The pet at its own size, to animate: the enlargement is applied after each animation frame, the way the
		 * game draws scaled NPCs. (Enlarging first breaks skeletal animations, which move bones by fixed amounts.)
		 * Null to animate {@link #model} directly.
		 */
		Model base;
		/** How much {@link #base} is enlarged (sideways, up) and lowered (model units) after animating. */
		float scaleX = 1, scaleY = 1, hover;
		/** A floating pet: kept at riding height even when its animation flies it up or down. */
		boolean floating;
		/** Ridden on the shoulders (a two-legged pet): no saddle or reins. */
		boolean shoulders;

		Built(int npcId, String petName, Model model, int a, int b, int c, float wa, float wb, float wc,
			int mountHeight, RiderPose autoPose, Color[] palette, short trim)
		{
			this.npcId = npcId;
			this.petName = petName;
			this.model = model;
			this.a = a;
			this.b = b;
			this.c = c;
			this.wa = wa;
			this.wb = wb;
			this.wc = wc;
			this.mountHeight = mountHeight;
			this.autoPose = autoPose;
			this.palette = palette;
			this.trim = trim;
		}
	}

	private final Client client;

	PetModels(Client client)
	{
		this.client = client;
	}

	static NPCComposition compositionOf(NPC pet)
	{
		NPCComposition comp = pet.getTransformedComposition();
		return comp != null ? comp : pet.getComposition();
	}

	static String nameOf(NPCComposition comp)
	{
		return comp == null || comp.getName() == null ? null : Text.removeTags(comp.getName());
	}

	/**
	 * Real pets, unlike quest companions and other followers, can be picked up. (The follower flag isn't used:
	 * the game's "Move follower options lower down" setting changes it.)
	 */
	static boolean isOwnablePet(NPCComposition comp)
	{
		if (comp == null)
		{
			return false;
		}
		String[] actions = comp.getActions();
		if (actions == null)
		{
			return false;
		}
		for (String action : actions)
		{
			if (action != null && action.equalsIgnoreCase("Pick-up"))
			{
				return true;
			}
		}
		return false;
	}

	/** Loads the pet's models merged and recoloured, at their original size. Null if not loaded yet. */
	ModelData load(NPCComposition comp)
	{
		int[] modelIds = comp.getModels();
		if (modelIds == null || modelIds.length == 0)
		{
			return null;
		}

		ModelData[] parts = new ModelData[modelIds.length];
		for (int i = 0; i < modelIds.length; i++)
		{
			parts[i] = client.loadModelData(modelIds[i]);
			if (parts[i] == null)
			{
				return null;
			}
		}

		ModelData md = client.mergeModels(parts)
			.cloneVertices()
			.cloneColors();

		short[] find = comp.getColorToReplace();
		short[] repl = comp.getColorToReplaceWith();
		if (find != null && repl != null)
		{
			for (int i = 0; i < Math.min(find.length, repl.length); i++)
			{
				md.recolor(find[i], repl[i]);
			}
		}
		return md;
	}

	static PetRules.Shape measure(ModelData md, NPCComposition comp)
	{
		float[] xs = md.getVerticesX();
		float[] ys = md.getVerticesY();
		float[] zs = md.getVerticesZ();
		float minX = 0, maxX = 0, minY = 0, maxY = 0, minZ = 0, maxZ = 0;
		for (int i = 0; i < md.getVerticesCount(); i++)
		{
			minX = Math.min(minX, xs[i]);
			maxX = Math.max(maxX, xs[i]);
			minY = Math.min(minY, ys[i]);
			maxY = Math.max(maxY, ys[i]);
			minZ = Math.min(minZ, zs[i]);
			maxZ = Math.max(maxZ, zs[i]);
		}
		float ws = (comp.getWidthScale() > 0 ? comp.getWidthScale() : SCALE_BASE) / (float) SCALE_BASE;
		float hs = (comp.getHeightScale() > 0 ? comp.getHeightScale() : SCALE_BASE) / (float) SCALE_BASE;

		// Model Y points down: the top is at -minY, and maxY < 0 means the model's lowest point is above the ground.
		float height = -minY * hs;
		float lift = Math.max(0, -maxY) * hs;
		float footprint = Math.max(maxX - minX, maxZ - minZ) * ws;
		return new PetRules.Shape(height, lift, footprint);
	}

	/**
	 * Makes the mount for this pet.
	 *
	 * @param sizeScale the player's size settings (1 = as fitted)
	 * @return the mount, or null if the pet's models aren't loaded yet or no seat could be found
	 */
	Built build(NPCComposition comp, float sizeScale)
	{
		ModelData md = load(comp);
		if (md == null)
		{
			return null;
		}

		// A few pets' idle animation moves the whole model: the heron's lifts it about 220 units off a model that
		// sits below the ground. Measure everything (size, seat, how high it floats) on the pet as it really
		// stands. The animation itself already moves each frame, so this only changes the measurements.
		int shift = idleShift(comp);
		if (shift != 0)
		{
			md.translate(0, shift, 0);
		}

		int ws = comp.getWidthScale() > 0 ? comp.getWidthScale() : SCALE_BASE;
		int hs = comp.getHeightScale() > 0 ? comp.getHeightScale() : SCALE_BASE;

		// A tuned seat is only valid for the exact model it was measured on.
		MountFits.Fit fit = MountFits.get(comp.getId());
		if (fit != null && fit.vertexCount != md.getVerticesCount())
		{
			log.debug("Pet {} model changed since tuning ({} vs {} vertices); finding a seat automatically",
				comp.getId(), md.getVerticesCount(), fit.vertexCount);
			fit = null;
		}

		// Everything done to the model below, so the same can be done after each animation frame.
		float fx = 1, fy = 1, hover = 0;

		// How much to enlarge the pet: tuned, or grown until its back is about pony height.
		float growth;
		if (fit != null)
		{
			growth = fit.growth;
		}
		else
		{
			md.scale(ws, hs, ws); // the pet at its normal in-game size, to measure it
			fx *= ws / (float) SCALE_BASE;
			fy *= hs / (float) SCALE_BASE;
			SeatFinder.Seat found = findSeat(md);
			float seatHeight = found != null ? found.height - Math.max(0, -maxY(md)) : -minY(md) * 0.6f;
			growth = MountSizing.growthFactor(Math.round(seatHeight), TARGET_SEAT_HEIGHT, MAX_GROWTH, 1f);
			ws = hs = SCALE_BASE; // already applied
		}
		growth *= sizeScale;

		md.scale(Math.round(ws * growth), Math.round(hs * growth), Math.round(ws * growth));
		fx *= Math.round(ws * growth) / (float) SCALE_BASE;
		fy *= Math.round(hs * growth) / (float) SCALE_BASE;

		// Floating pets: bring them down to a gentle hover so the rider isn't up in the air.
		// Model Y points down, so a negative lowest point means the model floats above the ground.
		float lowest = maxY(md);
		boolean floating = lowest < -MAX_HOVER;
		if (floating)
		{
			md.translate(0, Math.round(-lowest - MAX_HOVER), 0);
			hover = Math.round(-lowest - MAX_HOVER);
		}
		else if (lowest > MAX_HOVER)
		{
			// Standing in a hole (an idle that sinks the pet, like a swimming muttadile): back up onto the ground.
			md.translate(0, Math.round(-lowest), 0);
			hover = Math.round(-lowest);
		}

		// Tuned pets were fitted for a seat at horse height: bring the seat down to pony height. And keep long,
		// wide and tall pets to a sensible size. Never smaller than the pet itself.
		boolean shoulders = fit != null && fit.shoulders;
		float cap = shoulders ? 1f : capFactor(md, sizeScale);
		if (fit != null)
		{
			// Shoulder rides sit higher: the pet is a giant carrying you, not a pony.
			float seat = seatHeight(md, fit.a, fit.b, fit.c, fit.wa, fit.wb, fit.wc);
			int target = shoulders ? SHOULDER_SEAT_HEIGHT : TARGET_SEAT_HEIGHT;
			cap = Math.min(cap, target * sizeScale / Math.max(1f, seat));
		}
		float fitted = Math.max(cap, Math.min(1f, sizeScale / growth));
		if (fitted < 1f)
		{
			int s = Math.max(1, Math.round(SCALE_BASE * fitted));
			md.scale(s, s, s);
			growth *= s / (float) SCALE_BASE;
			fx *= s / (float) SCALE_BASE;
			fy *= s / (float) SCALE_BASE;
			hover *= s / (float) SCALE_BASE;
		}
		int mountHeight = Math.max(1, Math.round(-minY(md)));

		// The seat and pose: tuned, or found on the enlarged model.
		RiderPose autoPose;
		int sa, sb, sc;
		float swa, swb, swc;
		if (fit != null)
		{
			autoPose = poseForSeat(fit.pose, seatHeight(md, fit.a, fit.b, fit.c, fit.wa, fit.wb, fit.wc));
			sa = fit.a;
			sb = fit.b;
			sc = fit.c;
			swa = fit.wa;
			swb = fit.wb;
			swc = fit.wc;
		}
		else
		{
			SeatFinder.Seat found = findSeat(md);
			if (found == null)
			{
				return null;
			}
			autoPose = floating ? RiderPose.CROSS_LEGGED
				: poseForSeat(halfWidthAt(md, found) >= EXTRA_WIDE_HALF_WIDTH ? RiderPose.EXTRA_WIDE : RiderPose.WIDE,
				-(found.wa * md.getVerticesY()[found.a] + found.wb * md.getVerticesY()[found.b]
					+ found.wc * md.getVerticesY()[found.c]));
			sa = found.a;
			sb = found.b;
			sc = found.c;
			swa = found.wa;
			swb = found.wb;
			swc = found.wc;
		}

		Color[] palette = PetPalette.fromModel(md.getFaceColors(), md.getFaceTextures());
		short trim = SaddleMesh.trimFor(md.getFaceColors(), md.getFaceTransparencies());

		// Lit exactly as the game lights this NPC, so the mount looks like the pet you know.
		int[] lighting = MountFits.lighting(comp.getId());
		Model model = md.light(NPC_AMBIENT + lighting[0], NPC_CONTRAST + lighting[1] * 5, -30, -50, -30);
		if (model == null)
		{
			return null;
		}

		int[] mapped = null;
		if (model.getVerticesCount() != md.getVerticesCount())
		{
			// The lit model numbers its vertices differently. Keep the fitted seat by finding the same points on it.
			mapped = mapVertices(md, model, sa, sb, sc);
			if (mapped != null)
			{
				sa = mapped[0];
				sb = mapped[1];
				sc = mapped[2];
			}
		}
		if (model.getVerticesCount() != md.getVerticesCount() && mapped == null)
		{
			// Couldn't match them up: find the seat on the lit model directly.
			SeatFinder.Seat onModel = SeatFinder.find(model.getVerticesX(), model.getVerticesY(), model.getVerticesZ(),
				model.getVerticesCount(), model.getFaceIndices1(), model.getFaceIndices2(), model.getFaceIndices3(),
				model.getFaceTransparencies(), model.getFaceCount());
			if (onModel == null)
			{
				return null;
			}
			sa = onModel.a;
			sb = onModel.b;
			sc = onModel.c;
			swa = onModel.wa;
			swb = onModel.wb;
			swc = onModel.wc;
		}

		Built built = new Built(comp.getId(), nameOf(comp), model, sa, sb, sc, swa, swb, swc, mountHeight, autoPose,
			palette, trim);
		built.floating = floating;
		built.shoulders = shoulders;

		// The pet at its own size, lit the same way, for animating before enlarging.
		ModelData raw = load(comp);
		Model base = raw == null ? null
			: raw.light(NPC_AMBIENT + lighting[0], NPC_CONTRAST + lighting[1] * 5, -30, -50, -30);
		if (base != null && base.getVerticesCount() == model.getVerticesCount())
		{
			built.base = base;
			built.scaleX = fx;
			built.scaleY = fy;
			built.hover = hover;
		}

		log.debug("Built mount for npc {} ({}): {}, growth {}x, pose {}",
			comp.getId(), comp.getName(), fit != null ? "tuned" : "automatic", growth, autoPose);
		return built;
	}

	/** Below this, an idle animation is just the pet breathing, not moving the whole model. */
	private static final int MIN_IDLE_SHIFT = 16;

	/**
	 * How far the pet's idle animation moves the whole model up or down (y down), or 0 for the usual small
	 * movements. The median vertex movement, so flapping wings or a wagging tail don't count.
	 */
	private int idleShift(NPCComposition comp)
	{
		int npcId = comp.getId();
		int[] anims = MountFits.animations(npcId);
		if (anims == null || anims[0] == -1)
		{
			return 0;
		}
		try
		{
			Animation idle = client.loadAnimation(anims[0]);
			ModelData md = load(comp); // a separate copy, so lighting it here can't affect the mount
			Model probe = md == null ? null : md.light(NPC_AMBIENT, NPC_CONTRAST, -30, -50, -30);
			if (idle == null || probe == null)
			{
				return 0;
			}
			float[] rest = probe.getVerticesY().clone();
			int n = probe.getVerticesCount();
			Model posed = client.applyTransformations(probe, idle, 0, null, 0);
			if (posed == null || posed.getVerticesCount() != n || n == 0)
			{
				return 0;
			}
			float[] ys = posed.getVerticesY();
			float[] moved = new float[n];
			for (int v = 0; v < n; v++)
			{
				moved[v] = ys[v] - rest[v];
			}
			java.util.Arrays.sort(moved);
			int shift = Math.round(moved[n / 2]);
			return Math.abs(shift) >= MIN_IDLE_SHIFT ? shift : 0;
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't measure the idle pose of npc {}", npcId, e);
			return 0;
		}
	}

	/** The lit model's vertices at the same places as these model-data vertices, or null if any is missing. */
	private static int[] mapVertices(ModelData md, Model model, int... vertices)
	{
		float[] mx = md.getVerticesX(), my = md.getVerticesY(), mz = md.getVerticesZ();
		float[] lx = model.getVerticesX(), ly = model.getVerticesY(), lz = model.getVerticesZ();
		int[] out = new int[vertices.length];
		for (int i = 0; i < vertices.length; i++)
		{
			int v = vertices[i];
			if (v < 0 || v >= md.getVerticesCount())
			{
				return null;
			}
			int best = -1;
			float bestD = 0.5f;
			for (int j = 0; j < model.getVerticesCount(); j++)
			{
				float d = Math.abs(lx[j] - mx[v]) + Math.abs(ly[j] - my[v]) + Math.abs(lz[j] - mz[v]);
				if (d < bestD)
				{
					bestD = d;
					best = j;
				}
			}
			if (best < 0)
			{
				return null;
			}
			out[i] = best;
		}
		return out;
	}

	/** How much to shrink this (enlarged) pet to keep it within the biggest mount size, or 1 if it fits. */
	private static float capFactor(ModelData md, float sizeScale)
	{
		float[] xs = md.getVerticesX(), ys = md.getVerticesY(), zs = md.getVerticesZ();
		int[] f1 = md.getFaceIndices1(), f2 = md.getFaceIndices2(), f3 = md.getFaceIndices3();
		byte[] alphas = md.getFaceTransparencies();
		float minX = Float.MAX_VALUE, maxX = -Float.MAX_VALUE, minZ = Float.MAX_VALUE, maxZ = -Float.MAX_VALUE, top = 0;
		for (int f = 0; f < md.getFaceCount(); f++)
		{
			if (alphas != null && (alphas[f] & 0xFF) >= 254)
			{
				continue; // invisible faces don't count
			}
			for (int v : new int[]{f1[f], f2[f], f3[f]})
			{
				minX = Math.min(minX, xs[v]);
				maxX = Math.max(maxX, xs[v]);
				minZ = Math.min(minZ, zs[v]);
				maxZ = Math.max(maxZ, zs[v]);
				top = Math.min(top, ys[v]);
			}
		}
		if (minX > maxX)
		{
			return 1f;
		}
		float cap = 1f;
		cap = Math.min(cap, MAX_LENGTH * sizeScale / Math.max(1f, maxZ - minZ));
		cap = Math.min(cap, MAX_WIDTH * sizeScale / Math.max(1f, maxX - minX));
		cap = Math.min(cap, MAX_HEIGHT * sizeScale / Math.max(1f, -top));
		return cap;
	}

	/** The pose, or a lower one if the seat is too low for it. */
	static RiderPose poseForSeat(RiderPose pose, float seatHeight)
	{
		if (pose == RiderPose.WIDE && seatHeight < MIN_WIDE_SEAT)
		{
			pose = RiderPose.EXTRA_WIDE;
		}
		if (pose == RiderPose.EXTRA_WIDE && seatHeight < MIN_EXTRA_WIDE_SEAT)
		{
			pose = RiderPose.CROSS_LEGGED;
		}
		return pose;
	}

	private static float seatHeight(ModelData md, int a, int b, int c, float wa, float wb, float wc)
	{
		float[] ys = md.getVerticesY();
		return -(wa * ys[a] + wb * ys[b] + wc * ys[c]);
	}

	private static SeatFinder.Seat findSeat(ModelData md)
	{
		return SeatFinder.find(md.getVerticesX(), md.getVerticesY(), md.getVerticesZ(), md.getVerticesCount(),
			md.getFaceIndices1(), md.getFaceIndices2(), md.getFaceIndices3(), md.getFaceTransparencies(), md.getFaceCount());
	}

	/** How far the body reaches to either side around the seat. */
	private static float halfWidthAt(ModelData md, SeatFinder.Seat s)
	{
		float[] xs = md.getVerticesX();
		float[] zs = md.getVerticesZ();
		float seatZ = s.wa * zs[s.a] + s.wb * zs[s.b] + s.wc * zs[s.c];
		float seatX = s.wa * xs[s.a] + s.wb * xs[s.b] + s.wc * xs[s.c];
		float half = 0;
		for (int v = 0; v < md.getVerticesCount(); v++)
		{
			if (Math.abs(zs[v] - seatZ) < 12)
			{
				half = Math.max(half, Math.abs(xs[v] - seatX));
			}
		}
		return half;
	}

	private static float maxY(ModelData md)
	{
		float[] ys = md.getVerticesY();
		float max = Float.NEGATIVE_INFINITY;
		for (int i = 0; i < md.getVerticesCount(); i++)
		{
			max = Math.max(max, ys[i]);
		}
		return max == Float.NEGATIVE_INFINITY ? 0 : max;
	}

	private static float minY(ModelData md)
	{
		float[] ys = md.getVerticesY();
		float min = 0;
		for (int i = 0; i < md.getVerticesCount(); i++)
		{
			min = Math.min(min, ys[i]);
		}
		return min;
	}
}

