			}

			@Override
			public void toggleFavourite(int npcId)
			{
				java.util.Set<Integer> favs = favourites();
				if (!favs.remove(npcId))
				{
					favs.add(npcId);
				}
				configManager.setConfiguration(PetMountsConfig.GROUP, "favouriteMounts", joinIds(favs));
