package com.petmounts;

import java.awt.Point;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.List;

/** The outline around a set of points on screen (their convex hull). */
final class ScreenHull
{
	private ScreenHull()
	{
	}

	static Polygon of(List<Point> points)
	{
		List<Point> sorted = new ArrayList<>(points);
		sorted.sort((a, b) -> a.x != b.x ? Integer.compare(a.x, b.x) : Integer.compare(a.y, b.y));
		int n = sorted.size();
		Point[] hull = new Point[2 * n];
		int k = 0;
		for (int i = 0; i < n; i++)
		{
			while (k >= 2 && cross(hull[k - 2], hull[k - 1], sorted.get(i)) <= 0)
			{
				k--;
			}
			hull[k++] = sorted.get(i);
		}
		for (int i = n - 2, lower = k + 1; i >= 0; i--)
		{
			while (k >= lower && cross(hull[k - 2], hull[k - 1], sorted.get(i)) <= 0)
			{
				k--;
			}
			hull[k++] = sorted.get(i);
		}
		Polygon polygon = new Polygon();
		for (int i = 0; i < Math.max(0, k - 1); i++)
		{
			polygon.addPoint(hull[i].x, hull[i].y);
		}
		return polygon;
	}

	private static long cross(Point o, Point a, Point b)
	{
		return (long) (a.x - o.x) * (b.y - o.y) - (long) (a.y - o.y) * (b.x - o.x);
	}
}

package com.petmounts;

/**
 * Finds a seat on a pet the plugin has no tuned seat for (for example a pet released after this version).
 *
 * It drops a line straight down through the middle of the pet's body and takes the highest solid triangle it
 * hits: that point on the pet's back is where the rider sits. The same method was used, on the game's models,
 * to build {@link MountFits}.
 *
 * Coordinates are model space: x sideways, y pointing down, z toward the tail.
 */
final class SeatFinder
{
	/** Faces at least this transparent are effects (smoke, glow), not something to sit on. */
	static final int SOLID_ALPHA = 128;

	static final class Seat
	{
		final int a, b, c;
		final float wa, wb, wc;
		/** Height of the seat above the model's origin (up is positive). */
		final float height;

		Seat(int a, int b, int c, float wa, float wb, float wc, float height)
		{
			this.a = a;
			this.b = b;
			this.c = c;
			this.wa = wa;
			this.wb = wb;
			this.wc = wc;
			this.height = height;
		}
	}

	private SeatFinder()
	{
	}

	/**
	 * @param alphas face transparency (0 = opaque, 255 = invisible), or null if every face is opaque
	 * @return the seat under the middle of the body, or null if nothing solid was found
	 */
	static Seat find(float[] xs, float[] ys, float[] zs, int vertexCount,
		int[] f1, int[] f2, int[] f3, byte[] alphas, int faceCount)
	{
		// Seat front-to-back: the middle of the body's surface area. Thin necks and tails count for little.
		double areaSum = 0, zSum = 0;
		for (int f = 0; f < faceCount; f++)
		{
			if (!solid(alphas, f))
			{
				continue;
			}
			int a = f1[f], b = f2[f], c = f3[f];
			double ux = xs[b] - xs[a], uy = ys[b] - ys[a], uz = zs[b] - zs[a];
			double vx = xs[c] - xs[a], vy = ys[c] - ys[a], vz = zs[c] - zs[a];
			double cx = uy * vz - uz * vy, cy = uz * vx - ux * vz, cz = ux * vy - uy * vx;
			double area = Math.sqrt(cx * cx + cy * cy + cz * cz);
			areaSum += area;
			zSum += area * (zs[a] + zs[b] + zs[c]) / 3.0;
		}
		if (areaSum <= 0)
		{
			return null;
		}
		float seatZ = (float) (zSum / areaSum);

		// Seat side-to-side: the body's centre line, unless the model is built off-centre.
		float minX = Float.MAX_VALUE, maxX = -Float.MAX_VALUE;
		for (int v = 0; v < vertexCount; v++)
		{
			if (Math.abs(zs[v] - seatZ) < 8)
			{
				minX = Math.min(minX, xs[v]);
				maxX = Math.max(maxX, xs[v]);
			}
		}
		float seatX = 0;
		if (minX <= maxX)
		{
			float mid = (minX + maxX) / 2, half = (maxX - minX) / 2;
			seatX = Math.abs(mid) < 0.3f * half ? 0 : mid;
		}

		// Step sideways if the line slips through a gap between triangles.
		for (float dx : new float[]{0, 2, -2, 5, -5, 9, -9})
		{
			Seat s = raycast(xs, ys, zs, f1, f2, f3, alphas, faceCount, seatX + dx, seatZ);
			if (s != null)
			{
				return s;
			}
		}
		return null;
	}

	/** The highest solid triangle directly under (x, z). */
	static Seat raycast(float[] xs, float[] ys, float[] zs, int[] f1, int[] f2, int[] f3,
		byte[] alphas, int faceCount, float x, float z)
	{
		return raycast(xs, ys, zs, f1, f2, f3, alphas, faceCount, x, z, Float.MAX_VALUE);
	}

	/** The highest solid triangle directly under (x, z) that is no higher than maxHeight. */
	static Seat raycast(float[] xs, float[] ys, float[] zs, int[] f1, int[] f2, int[] f3,
		byte[] alphas, int faceCount, float x, float z, float maxHeight)
	{
		Seat best = null;
		for (int f = 0; f < faceCount; f++)
		{
			if (!solid(alphas, f))
			{
				continue;
			}
			int a = f1[f], b = f2[f], c = f3[f];
			float ax = xs[a], az = zs[a], bx = xs[b], bz = zs[b], cx = xs[c], cz = zs[c];
			float d = (bz - cz) * (ax - cx) + (cx - bx) * (az - cz);
			if (Math.abs(d) < 1e-6f)
			{
				continue; // seen edge-on from above
			}
			float wa = ((bz - cz) * (x - cx) + (cx - bx) * (z - cz)) / d;
			float wb = ((cz - az) * (x - cx) + (ax - cx) * (z - cz)) / d;
			float wc = 1 - wa - wb;
			if (wa < -1e-4f || wb < -1e-4f || wc < -1e-4f)
			{
				continue;
			}
			float height = -(wa * ys[a] + wb * ys[b] + wc * ys[c]);
			if (height > maxHeight)
			{
				continue;
			}
			if (best == null || height > best.height)
			{
				best = new Seat(a, b, c, wa, wb, wc, height);
			}
		}
		return best;
	}

	private static boolean solid(byte[] alphas, int face)
	{
		return alphas == null || (alphas[face] & 0xFF) < SOLID_ALPHA;
	}
}

package com.petmounts;

import net.runelite.api.Model;

/**
 * Follows one spot on the mount's back as the mount animates.
 *
 * RuneLite objects can't be attached to another object's bones, so the seat is stored as a triangle on the
 * mount and a position inside it. Each frame the triangle's three vertices are read from the animated model and
 * the seat is rebuilt from them, so the rider rises, dips and sways with the pet's back.
 *
 * The idea of tracking the mount's vertices to move a separately drawn rider comes from Rapid Mounts by
 * RapidUrsa (BSD 2-Clause); see THIRD_PARTY_NOTICES.md.
 */
final class SeatTracker
{
	private int a = -1, b, c;
	private float wa, wb, wc;
	private int vertexCount;

	/** Where the seat is at rest, and how far it may move from there (guards against a bad frame). */
	private float restX, restY, restZ;
	private float maxMove;
	/** Frames in a row that looked implausible. */
	private int rejected;
	/** After this many, the animation really does hold the seat there: follow it. */
	private static final int MAX_REJECTED = 25;

	/** Current seat in model space: x sideways, y pointing down, z toward the tail. */
	float x, y, z;

	void set(int a, int b, int c, float wa, float wb, float wc, Model rest, float mountHeight)
	{
		this.a = a;
		this.b = b;
		this.c = c;
		this.wa = wa;
		this.wb = wb;
		this.wc = wc;
		this.vertexCount = rest.getVerticesCount();
		// Hopping and flying pets really do move this far in their walk; only a jump beyond it is a bad frame.
		this.maxMove = Math.max(40, mountHeight);
		read(rest);
		restX = x;
		restY = y;
		restZ = z;
	}

	boolean isSet()
	{
		return a >= 0;
	}

	void clear()
	{
		a = -1;
	}

	/** Reads the seat from the mount's current animation frame. */
	void update(Model animated)
	{
		if (a < 0 || animated == null || animated.getVerticesCount() != vertexCount)
		{
			return;
		}
		float px = x, py = y, pz = z;
		read(animated);
		if (Math.abs(x - restX) > maxMove || Math.abs(y - restY) > maxMove || Math.abs(z - restZ) > maxMove)
		{
			if (++rejected < MAX_REJECTED)
			{
				// A frame moved the seat somewhere implausible: keep the last good position.
				x = px;
				y = py;
				z = pz;
				return;
			}
			// Not one bad frame: the pet's animation keeps the seat here, so this is where the rider belongs.
			restX = x;
			restY = y;
			restZ = z;
		}
		rejected = 0;
	}

	private void read(Model m)
	{
		float[] xs = m.getVerticesX();
		float[] ys = m.getVerticesY();
		float[] zs = m.getVerticesZ();
		x = wa * xs[a] + wb * xs[b] + wc * xs[c];
		y = wa * ys[a] + wb * ys[b] + wc * ys[c];
		z = wa * zs[a] + wb * zs[b] + wc * zs[c];
	}
}

package com.petmounts;

import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;

/** Works out how fast a player is moving from how far they move each client tick. */
final class SpeedTracker
{
	/** Local units moved per client tick above which a player is running (walk ~4, run ~8). */
	static final int RUN_SPEED = 6;
	/** Client ticks to keep moving after the last step, so walk and idle don't flicker between tiles. */
	private static final int LINGER = 5;

	private int lastX = Integer.MIN_VALUE;
	private int lastY = Integer.MIN_VALUE;
	private int speed;
	private int lingering;
	private boolean movedThisTick;

	void track(Player player)
	{
		LocalPoint lp = player.getLocalLocation();
		if (lp == null)
		{
			return;
		}
		if (lastX != Integer.MIN_VALUE)
		{
			int moved = Math.max(Math.abs(lp.getX() - lastX), Math.abs(lp.getY() - lastY));
			movedThisTick = moved > 0;
			if (moved > 0)
			{
				// A big jump is a teleport, not a step.
				speed = moved > 4 * 128 ? 0 : moved;
				lingering = LINGER;
			}
			else if (lingering > 0)
			{
				lingering--;
			}
			else
			{
				speed = 0;
			}
		}
		lastX = lp.getX();
		lastY = lp.getY();
	}

	int speed()
	{
		return speed;
	}

	boolean isMoving()
	{
		return speed > 0;
	}

	boolean isRunning()
	{
		return speed >= RUN_SPEED;
	}

	boolean movedThisTick()
	{
		return movedThisTick;
	}

	/** 0 standing, 1 walking, 2 running. */
	int gait()
	{
		return speed == 0 ? 0 : isRunning() ? 2 : 1;
	}
}

package com.petmounts;

import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import org.junit.Test;
import static org.junit.Assert.assertTrue;

public class ConfigTypesTest
{
	/**
	 * RuneLite reads each setting through a generated proxy class, which can only use public types. A setting
	 * whose type isn't public throws on every read, every frame, and freezes the game.
	 */
	@Test
	public void everySettingTypeIsPublic()
	{
		for (Method m : PetMountsConfig.class.getDeclaredMethods())
		{
			Class<?> type = m.getReturnType();
			if (type.isPrimitive() || type.getName().startsWith("java."))
			{
				continue;
			}
			assertTrue("Setting " + m.getName() + " uses " + type.getSimpleName() + ", which must be public",
				Modifier.isPublic(type.getModifiers()));
		}
	}
}

