		assertTrue(PetRules.check(6638, "Kalphite Princess", null, NONE, NONE).rideable);
		assertFalse(PetRules.check(6637, "Kalphite Princess", null, NONE, NONE).rideable);
	}

	@Test
	public void unlistedPetsAreJudgedByShape()
	{
		assertTrue(PetRules.check(0, "Brand new pet", new PetRules.Shape(80, 0, 120), NONE, NONE).rideable);
		assertTrue(PetRules.check(0, "Brand new pet", new PetRules.Shape(120, 50, 60), NONE, NONE).rideable);
		assertEquals(PetRules.Reason.HUMANOID, PetRules.check(0, "Brand new pet", new PetRules.Shape(150, 0, 60), NONE, NONE).reason);
	}

	@Test
	public void playerListsWin()
	{
		Set<String> allow = PetRules.parseList("Olmlet, Nexling");
		Set<String> deny = PetRules.parseList("baby mole");
		assertTrue(PetRules.check(0, "Olmlet", null, allow, deny).rideable);
		assertFalse(PetRules.check(0, "Baby Mole", null, allow, deny).rideable);
	}
}

package com.petmounts;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class ReinMeshTest
{
	@Test
	public void fitsInTheSaddleTemplate()
	{
		ReinMesh m = new ReinMesh();
		assertTrue(m.vertexCount() <= 394 && m.faceCount() <= 788);
		for (int f = 0; f < m.faceCount(); f++)
		{
			assertTrue(m.f1[f] < m.vertexCount() && m.f2[f] < m.vertexCount() && m.f3[f] < m.vertexCount());
		}
	}

	@Test
	public void runsFromHandToMouthAndHangs()
	{
		ReinMesh m = new ReinMesh();
		float[] hand = {-8, -140, -30};
		float[] mouth = {-6, -90, -110};
		m.update(new float[][]{hand, {8, -140, -30}}, new float[][]{mouth, {6, -90, -110}});
		float[] start = ring(m, 0), end = ring(m, ReinMesh.SEGMENTS), mid = ring(m, ReinMesh.SEGMENTS / 2);
		for (int k = 0; k < 3; k++)
		{
			assertEquals(hand[k], start[k], 0.01);
			assertEquals(mouth[k], end[k], 0.01);
		}
		float straightY = (hand[1] + mouth[1]) / 2;
		assertTrue("the middle hangs below a straight line (y points down)", mid[1] > straightY + 5);
		for (int v = 0; v < m.vertexCount(); v++)
		{
			assertTrue(!Float.isNaN(m.x[v]) && !Float.isNaN(m.y[v]) && !Float.isNaN(m.z[v]));
		}
	}

	@Test
	public void noHandsFreeWhenSittingOnTop()
	{
		assertNull(ReinMesh.handsFor(RiderPose.CROSS_LEGGED));
		assertNull(ReinMesh.handsFor(RiderPose.STANDING));
		assertNotNull(ReinMesh.handsFor(RiderPose.WIDE));
		assertNotNull(ReinMesh.handsFor(RiderPose.EXTRA_WIDE));
		assertNotNull(ReinMesh.handsFor(RiderPose.SADDLE));
	}

	@Test
	public void findsTheCornersOfTheMouth()
	{
		// A blocky horse: body from z -60 to 60 at 60-100 high, a head in front at z -100 to -70, 90-130 high.
		Shape s = new Shape();
		s.box(-20, 20, 60, 100, -60, 60);
		s.box(-10, 10, 90, 130, -100, -70);
		int[] bit = s.findBit(0, 100);
		assertNotNull(bit);
		assertTrue("left then right", s.x(bit[0]) < 0 && s.x(bit[1]) > 0);
		assertEquals(-100, s.z(bit[0]), 0.01);
		assertEquals(90, -s.y(bit[0]), 0.01);
	}

	@Test
	public void noMouthOnARoundOrb()
	{
		Shape s = new Shape();
		s.box(-30, 30, 10, 70, -30, 30); // nothing in front of the seat at head height
		assertNull(s.findBit(0, 70));
	}

	private static float[] ring(ReinMesh m, int s)
	{
		float[] c = new float[3];
		for (int k = 0; k < 3; k++)
		{
			int v = s * 3 + k;
			c[0] += m.x[v] / 3;
			c[1] += m.y[v] / 3;
			c[2] += m.z[v] / 3;
		}
		return c;
	}

	/** Boxes as triangles, in model space (y points down). */
	private static final class Shape
	{
		final List<float[]> v = new ArrayList<>();
		final List<int[]> f = new ArrayList<>();

		void box(float x0, float x1, float h0, float h1, float z0, float z1)
		{
			int o = v.size();
			for (int i = 0; i < 8; i++)
			{
				v.add(new float[]{(i & 1) == 0 ? x0 : x1, -((i & 2) == 0 ? h0 : h1), (i & 4) == 0 ? z0 : z1});
			}
			int[][] quads = {{0, 1, 3, 2}, {4, 5, 7, 6}, {0, 1, 5, 4}, {2, 3, 7, 6}, {0, 2, 6, 4}, {1, 3, 7, 5}};
			for (int[] q : quads)
			{
				f.add(new int[]{o + q[0], o + q[1], o + q[2]});
				f.add(new int[]{o + q[0], o + q[2], o + q[3]});
			}
		}

		float x(int i)
		{
			return v.get(i)[0];
		}

		float y(int i)
		{
			return v.get(i)[1];
		}

		float z(int i)
		{
			return v.get(i)[2];
		}

		int[] findBit(float seatZ, float seatHeight)
		{
			int n = v.size(), m = f.size();
			float[] xs = new float[n], ys = new float[n], zs = new float[n];
			for (int i = 0; i < n; i++)
			{
				xs[i] = x(i);
				ys[i] = y(i);
				zs[i] = z(i);
			}
			int[] a = new int[m], b = new int[m], c = new int[m];
			for (int i = 0; i < m; i++)
			{
				a[i] = f.get(i)[0];
				b[i] = f.get(i)[1];
				c[i] = f.get(i)[2];
			}
			return ReinMesh.findBit(xs, ys, zs, n, a, b, c, null, m, seatZ, seatHeight);
		}
	}
}

package com.petmounts;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RiderMotionTest
{
	private static final int ONE_SECOND = 50; // client ticks

	@Test
	public void dropsIntoTheSaddleAndSettles()
	{
		RiderMotion m = new RiderMotion();
		m.reset(true);
		assertTrue("starts above the seat", -m.y > RiderMotion.SETTLE_DROP - 2);
		float lowest = Float.MAX_VALUE;
		for (int i = 0; i < ONE_SECOND; i++)
		{
			m.update(0, 0, true);
			lowest = Math.min(lowest, -m.y);
		}
		assertTrue("never sinks far into the saddle", lowest >= -3.01f);
		assertTrue("gives a little bounce", lowest < 0);
		assertEquals(0, m.y, 1);
	}

	@Test
	public void swaysOnlyWhileMoving()
	{
		RiderMotion m = new RiderMotion();
		m.reset(false);
		for (int i = 0; i < ONE_SECOND; i++)
		{
			m.update(0, 0.25f, true);
		}
		assertEquals(0, m.x, 0.01);

		float widest = 0;
		for (int i = 0; i < 2 * ONE_SECOND; i++)
		{
			m.update(1, (i % 40) / 40f, true);
			widest = Math.max(widest, Math.abs(m.x));
		}
		assertTrue("gentle sway", widest > 1.5f && widest < 4f);
	}

	@Test
	public void rocksBackWhenSettingOffButNeverFar()
	{
		RiderMotion m = new RiderMotion();
		m.reset(false);
		m.update(0, 0, true);
		float furthest = 0;
		for (int i = 0; i < 20; i++)
		{
			m.update(2, 0, true); // straight into a run
			furthest = Math.max(furthest, m.z);
		}
		assertTrue("rocks toward the tail", furthest > 1.5f && furthest <= 6f);
	}

	@Test
	public void noJoltWhenFirstShown()
	{
		RiderMotion m = new RiderMotion();
		m.reset(false);
		m.update(2, 0, true); // someone already running when they come into view
		assertEquals(0, m.z, 0.5);
	}

	@Test
	public void stillWhenTurnedOff()
	{
		RiderMotion m = new RiderMotion();
		m.reset(true);
		m.update(2, 0.25f, false);
		assertEquals(0, m.x, 0);
		assertEquals(0, m.y, 0);
		assertEquals(0, m.z, 0);
	}

	@Test
	public void leansIntoTurnsAtARun()
	{
		RiderMotion m = new RiderMotion();
		m.reset(false);
		for (int i = 0; i < ONE_SECOND; i++)
		{
			m.update(2, 0, true, 32); // running, turning right
		}
		assertTrue("leans right (model -x)", m.x < -2.5f && m.x >= -5.01f);
		for (int i = 0; i < ONE_SECOND; i++)
		{
			m.update(0, 0, true, 32); // standing still: no lean
		}
		assertEquals(0, m.x, 0.3);
	}
}

package com.petmounts;

import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SaddleMeshTest
{
	/** A rounded back: level on top, falling away down the sides. */
	private static final SaddleMesh.Surface BACK = (dx, dz) -> Math.abs(dx) < 30 ? -dx * dx / 60f : Float.NaN;

	@Test
	public void fitsInTheTemplateAndSitsOnTheBack()
	{
		SaddleMesh m = SaddleMesh.build(BACK, 105, false, true, SaddleMesh.hsl(40, 5, 40), SaddleMesh.GOLD, SaddleStyle.CLASSIC, 788, 1576);
		assertTrue(m.vertexCount > 100 && m.vertexCount <= 788);
		assertTrue(m.faceCount > 100 && m.faceCount <= 1576);
		assertTrue("rider sits on top of the saddle", m.seatThickness > 3 && m.seatThickness < 12);
		for (int f = 0; f < m.faceCount; f++)
		{
			assertTrue(m.f1[f] < m.vertexCount && m.f2[f] < m.vertexCount && m.f3[f] < m.vertexCount);
		}
		for (int v = 0; v < m.vertexCount; v++)
		{
			assertTrue(!Float.isNaN(m.x[v]) && !Float.isNaN(m.y[v]) && !Float.isNaN(m.z[v]));
		}
	}

	@Test
	public void blanketOnlyForSittingCrossLegged()
	{
		SaddleMesh withSaddle = SaddleMesh.build(BACK, 105, false, true, (short) 0, (short) 0, SaddleStyle.CLASSIC, 788, 1576);
		SaddleMesh rug = SaddleMesh.build(BACK, 105, false, false, (short) 0, (short) 0, SaddleStyle.CLASSIC, 788, 1576);
		assertTrue(rug.faceCount < withSaddle.faceCount);
	}

	@Test
	public void neverOverflowsASmallTemplate()
	{
		SaddleMesh m = SaddleMesh.build(BACK, 105, true, true, (short) 0, (short) 0, SaddleStyle.CLASSIC, 120, 200);
		assertTrue(m.vertexCount <= 120 && m.faceCount <= 200);
	}

	@Test
	public void goldForWarmPetsSilverForDarkAndCoolOnes()
	{
		short brown = SaddleMesh.hsl(5, 4, 30);
		short black = SaddleMesh.hsl(0, 0, 10);
		short blue = SaddleMesh.hsl(38, 5, 60);
		short white = SaddleMesh.hsl(0, 0, 120);
		org.junit.Assert.assertEquals(SaddleMesh.GOLD, SaddleMesh.trimFor(new short[]{brown, brown, brown}, null));
		org.junit.Assert.assertEquals(SaddleMesh.SILVER, SaddleMesh.trimFor(new short[]{black, black, brown}, null));
		org.junit.Assert.assertEquals(SaddleMesh.SILVER, SaddleMesh.trimFor(new short[]{blue, blue, brown}, null));
		org.junit.Assert.assertEquals(SaddleMesh.GOLD, SaddleMesh.trimFor(new short[]{white, white, white}, null));
	}

	@Test
	public void blanketStaysInProportionOnBroadBacks()
	{
		SaddleMesh.Surface flat = (dx, dz) -> 0f; // a very broad, flat back
		SaddleMesh m = SaddleMesh.build(flat, 90, true, true, (short) 0, SaddleMesh.GOLD, SaddleStyle.CLASSIC, 788, 1576);
		float widest = 0, longest = 0;
		for (int v = 0; v < m.vertexCount; v++)
		{
			widest = Math.max(widest, Math.abs(m.x[v]));
			longest = Math.max(longest, Math.abs(m.z[v]));
		}
		assertTrue("blanket not wider than it should be", widest <= SaddleMesh.MAX_BLANKET_HALF_WIDTH + 6);
		assertTrue("blanket not longer than it should be", longest <= SaddleMesh.MAX_BLANKET_LENGTH / 2 + 6);
	}

	@Test
	public void saddleStylesChangeTheLeatherAndMetal()
	{
		SaddleMesh classic = SaddleMesh.build(BACK, 105, false, true, (short) 0, (short) 0, SaddleStyle.CLASSIC, 788, 1576);
		SaddleMesh skull = SaddleMesh.build(BACK, 105, false, true, (short) 0, (short) 0, SaddleStyle.SKULL, 788, 1576);
		java.util.Set<Short> a = new java.util.HashSet<>(), b = new java.util.HashSet<>();
		for (int i = 0; i < classic.faceCount; i++)
		{
			a.add(classic.color[i]);
		}
		for (int i = 0; i < skull.faceCount; i++)
		{
			b.add(skull.color[i]);
		}
		org.junit.Assert.assertTrue(a.contains(SaddleMesh.LEATHER));
		org.junit.Assert.assertFalse(b.contains(SaddleMesh.LEATHER));
		org.junit.Assert.assertTrue(b.contains(SaddleStyle.SKULL.metal));
		org.junit.Assert.assertEquals(classic.faceCount, skull.faceCount);
	}
}

package com.petmounts;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.Point;
import java.awt.Polygon;
import java.util.Arrays;
import org.junit.Test;

public class ScreenHullTest
{
	@Test
	public void outlinesTheOuterPoints()
	{
		Polygon p = ScreenHull.of(Arrays.asList(new Point(0, 0), new Point(10, 0), new Point(10, 10), new Point(0, 10),
			new Point(5, 5), new Point(3, 7)));
		assertEquals(4, p.npoints);
		assertTrue(p.contains(5, 5));
